import { type InferSelectModel, sql } from "drizzle-orm";
import {
  bigint,
  boolean,
  index,
  integer,
  pgTable,
  primaryKey,
  timestamp,
  uniqueIndex,
  varchar,
} from "drizzle-orm/pg-core";
import { timestamps } from "../utils/columns.helpers";
import { usersTable } from "./users";

/**
 * A vault groups records under one key (ADR 0001 D6). Ids are generated by the
 * client, so a vault can be created offline.
 */
export const vaultsTable = pgTable(
  "vaults",
  {
    vaultId: varchar().primaryKey(),

    ownerId: varchar()
      .notNull()
      .references(() => usersTable.userId, { onDelete: "cascade" }),

    kind: varchar({ enum: ["personal", "shared"] }).notNull(),
    // Bumped by a key rotation; members' wraps carry the version they hold.
    keyVersion: integer().notNull().default(1),
    // The last `records.seq` handed out in this vault. Taking the next one
    // locks this row until the write commits, so a vault's records commit in
    // `seq` order and a pull cursor never skips a row that commits late.
    lastSeq: bigint({ mode: "number" }).notNull().default(0),
    // What its record versions take up (`pushChangeBytes` each), counted against
    // the owner's storage quota. Kept up to date by every records write.
    usedBytes: bigint({ mode: "number" }).notNull().default(0),
    // A member left or was removed and still knows the current key: the next
    // owner or manager online rotates it (ADR 0001 D7), which clears this.
    keyRotationNeeded: boolean().notNull().default(false),

    // Name, icon, colour: encrypted with the vault key (AAD: vaultId).
    encryptedMeta: varchar().notNull(),
    metaEncryptionNonce: varchar().notNull(),

    ...timestamps,
  },
  (table) => [
    index("vaults_owner_idx").on(table.ownerId),
    // Exactly one personal (default) vault per user.
    uniqueIndex("vaults_one_personal_per_owner_idx")
      .on(table.ownerId)
      .where(sql`${table.kind} = 'personal' AND ${table.deleted_at} IS NULL`),
  ],
);

/**
 * A user's access to a vault. `encryptedVaultKey` is the vault key wrapped
 * under that member's account key (AAD: vaultId + keyVersion). Only `active`
 * members get access; `pending` is an invite not yet accepted (ADR 0001 D7).
 *
 * A key another member hands over is sealed to the member's public key
 * (`sealedVaultKey`, version `sealedKeyVersion`) by the sender's keypair: the
 * invite of a `pending` member (who has no wrap yet), or the new key after a
 * rotation by someone else (the member's wrap stays at the version they had).
 * The member turns it into their own wrap (`vault.acceptKey`), which clears it.
 */
export const vaultMembersTable = pgTable(
  "vault_members",
  {
    vaultId: varchar()
      .notNull()
      .references(() => vaultsTable.vaultId, { onDelete: "cascade" }),
    userId: varchar()
      .notNull()
      .references(() => usersTable.userId, { onDelete: "cascade" }),

    role: varchar({ enum: ["owner", "manage", "write", "read"] }).notNull(),
    status: varchar({ enum: ["active", "pending"] })
      .notNull()
      .default("active"),

    // The version of `encryptedVaultKey`; of the sealed key while `pending`.
    keyVersion: integer().notNull(),
    // Null while `pending`.
    encryptedVaultKey: varchar().unique(),
    vaultKeyEncryptionNonce: varchar().unique(),

    sealedVaultKey: varchar().unique(),
    sealedKeyVersion: integer(),
    // The recipient's keypair version the key is sealed to.
    sealedToKeyVersion: integer(),
    sealedByUserId: varchar().references(() => usersTable.userId, { onDelete: "set null" }),
    sealedByKeyVersion: integer(),

    updated_at: timestamp().defaultNow().notNull(),
    created_at: timestamp().defaultNow().notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.vaultId, table.userId] }),
    index("vault_members_user_idx").on(table.userId),
  ],
);

/**
 * A vault's earlier keys (ADR 0001 D7, rotation): key `keyVersion` wrapped
 * under key `keyVersion + 1` (AAD: vaultId + keyVersion). Append-only, one row
 * per rotation; whoever holds the current key walks them down to read history.
 */
export const vaultKeyLinksTable = pgTable(
  "vault_key_links",
  {
    vaultId: varchar()
      .notNull()
      .references(() => vaultsTable.vaultId, { onDelete: "cascade" }),
    keyVersion: integer().notNull(),
    encryptedVaultKey: varchar().notNull().unique(),
    vaultKeyEncryptionNonce: varchar().notNull().unique(),
    created_at: timestamp().defaultNow().notNull(),
  },
  (table) => [primaryKey({ columns: [table.vaultId, table.keyVersion] })],
);

export type VaultType = InferSelectModel<typeof vaultsTable>;
export type VaultMemberType = InferSelectModel<typeof vaultMembersTable>;
